using Mutagen.Bethesda.Plugins;
using Mutagen.Bethesda.Plugins.Binary.Headers;
using Mutagen.Bethesda.Plugins.Meta;
using Mutagen.Bethesda.Starfield;
using Shouldly;
using Xunit;
using static Mutagen.Bethesda.UnitTests.Plugins.Records.Starfield.StarfieldTestRecords;

namespace Mutagen.Bethesda.UnitTests.Plugins.Records.Starfield;

// Weapon fields per xEdit (wbDefinitionsSF1 RegisterRecordDef(WEAP)):
// - The record-level BNAM is the empty marker Is Embedded Weapon (21 weapons, all 0 bytes; the 46-byte BNAMs in
//   Starfield.esm belong to animation graph components).
// - WVIS starts with the Vec3 First Person Offset. Mutagen read it as three UInt32 (WVISUnknown1-3). The only values
//   in 406 weapons are 0 and 0x80000000, which is the float -0.0; it is written back bit for bit.
// CreatureRangedAttack_Mouth1_Fire is read whole (FULL and DESC left out: localized string IDs) with both readers and
// written back byte for byte; for MagShot, which has many localized names, only WVIS is compared.
public class WeaponEmbeddedAndOffsetTests
{
    private static IEnumerable<IWeaponGetter> Read(string hex)
        => ReadBoth<IWeaponGetter>(Record("WEAP", Hex(hex)), f => Weapon.CreateFromBinary(f), (s, p) => WeaponBinaryOverlay.WeaponFactory(s, p));

    // CreatureRangedAttack_Mouth1_Fire (0297F6:Starfield.esm)
    private const string MouthFire = "";

    // MagShot (02EB42:Starfield.esm)
    private const string MagShot = "";

    [Fact]
    public void EmbeddedWeaponMarker()
    {
        foreach (var weap in Read(MouthFire))
        {
            weap.IsEmbeddedWeapon.ShouldBeTrue();
            weap.FirstPersonOffset.X.ShouldBe(0f);
            var written = GameConstants.Starfield.MajorRecord(Write(w => weap.WriteToBinary(w)));
            written.Content.ToArray().ShouldBe(Hex(MouthFire));
        }
    }

    [Fact]
    public void FirstPersonOffset_NegativeZero()
    {
        var wvis = new RecordType("WVIS");
        var original = GameConstants.Starfield.MajorRecord(Record("WEAP", Hex(MagShot))).TryFindSubrecord(wvis)!.Value.Content.ToArray();
        foreach (var weap in Read(MagShot))
        {
            weap.IsEmbeddedWeapon.ShouldBeFalse();
            BitConverter.SingleToInt32Bits(weap.FirstPersonOffset.X).ShouldBe(unchecked((int)0x80000000));
            BitConverter.SingleToInt32Bits(weap.FirstPersonOffset.Y).ShouldBe(unchecked((int)0x80000000));
            BitConverter.SingleToInt32Bits(weap.FirstPersonOffset.Z).ShouldBe(unchecked((int)0x80000000));
            var written = GameConstants.Starfield.MajorRecord(Write(w => weap.WriteToBinary(w)));
            written.TryFindSubrecord(wvis)!.Value.Content.ToArray().ShouldBe(original);
        }
    }
}
